// Add alert box for CPC meetings
document.addEventListener('DOMContentLoaded', function() {
  // Only on /events/ pages
  if (!window.location.pathname.includes('/events/')) return;

  // Look for the department div and the CPA link
  var deptDiv = document.querySelector('div.department');
  if (!deptDiv) return;
  var cpaLink = deptDiv.querySelector('a[href*="community-preservation-act"]');
  if (!cpaLink) return;

  // Prevent duplicate alerts
  if (document.querySelector('.alert.view-empty')) return;

  // Find the "Event Documents" heading
  var evtHeading = document.querySelector('.block--views-block--event-documents-block-1 h2');
  if (!evtHeading) return;

  // Build the alert box
  var alertDiv = document.createElement('div');
  alertDiv.className = 'alert alert-warning alert-dismissible view-empty';
  alertDiv.setAttribute('role', 'alert');
  alertDiv.innerHTML = ''
    + '<p><em>CPC meeting materials can be found at <br />'
    + '<a target="_blank" href="https://www.somervillema.gov/cpcmeetingdocs">'
    + 'www.somervillema.gov/CPCMeetingDocs</a>.</em></p>'
    + '<button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>';

  // Insert it immediately after the heading
  evtHeading.parentNode.insertBefore(alertDiv, evtHeading.nextSibling);
});

(function () {
    /*
     * ============================================================
     * ELECTION WINNER HIGHLIGHTING
     * ============================================================
     *
     * The winner is determined ONLY by vote count.
     *
     * There are NO exclusions based on candidate name.
     * Therefore:
     *
     * - A named candidate can win
     * - A Write-in can win
     * - Blank can win
     * - A tie results in all tied winners being highlighted
     *
     * Councilor at Large is the only multi-seat race and
     * highlights the top 4 vote-getters.
     */
    const MULTI_SEAT_RACES = {
        "Councilor at Large": 4
    };
    /*
     * Convert the vote text into a number.
     * Handles values such as:
     * 1,234
     * 1,234 votes
     * —
     * blank
     */
    function parseVotes(value) {
        const cleaned = String(value || '').replace(/[^0-9.]/g, '');
        const number = parseFloat(cleaned);
        return isNaN(number) ? 0 : number;
    }
    /*
     * Get the race name from the race title row.
     * Removes the "# Votes" heading so it can be matched
     * against MULTI_SEAT_RACES.
     */
    function getRaceNameFromTitleRow(titleRow) {
        const titleElement =
            titleRow.querySelector('.raceTitle') || titleRow;
        const clone = titleElement.cloneNode(true);
        const votesHeading =
            clone.querySelector('.votesHeading');
        if (votesHeading) {
            votesHeading.remove();
        }
        return clone.textContent
            .trim()
            .replace(/\s+#\s*Votes\s*$/i, '')
            .trim();
    }
    /*
     * Highlight the top N vote-getters.
     *
     * Used for Councilor at Large, which has four seats.
     *
     * IMPORTANT:
     * There is intentionally NO check for "Blank" or "Write-in".
     * The vote total is the only determining factor.
     */
    function highlightTopNWinners(raceRows, numberOfWinners) {
        if (!raceRows.length || numberOfWinners <= 0) {
            return;
        }
        const ranked = [];
        for (const row of raceRows) {
            const cells = row.querySelectorAll('td');
            if (cells.length !== 2) {
                continue;
            }
            const votes = parseVotes(
                cells[1].innerText ||
                cells[1].textContent ||
                ''
            );
            ranked.push({
                row: row,
                votes: votes
            });
        }
        /*
         * If everyone has zero votes, don't highlight anything.
         */
        if (!ranked.some(item => item.votes > 0)) {
            return;
        }
        /*
         * Highest votes first.
         */
        ranked.sort(function (a, b) {
            return b.votes - a.votes;
        });
        /*
         * Determine the vote cutoff for the final winner.
         *
         * Example:
         * 500
         * 400
         * 300
         * 200
         * 100
         *
         * Top 4 means the cutoff is 200.
         */
        const cutoffIndex = Math.min(
            numberOfWinners - 1,
            ranked.length - 1
        );
        const cutoff = ranked[cutoffIndex]
            ? ranked[cutoffIndex].votes
            : 0;
        /*
         * Highlight everyone at or above the cutoff.
         *
         * This also means ties are handled fairly.
         */
        for (const item of ranked) {
            if (
                item.votes >= cutoff &&
                cutoff > 0
            ) {
                item.row.classList.add('winner');
            }
        }
    }
    /*
     * Highlight the winner of a normal single-seat race.
     *
     * The candidate's name is NOT checked.
     * Whoever has the most votes wins.
     */
    function highlightSingleWinner(raceRows) {
        let maxVotes = -Infinity;
        const winnerRows = [];
        for (const row of raceRows) {
            const cells = row.querySelectorAll('td');
            if (cells.length !== 2) {
                continue;
            }
            const votes = parseVotes(
                cells[1].innerText ||
                cells[1].textContent ||
                ''
            );
            if (votes > maxVotes) {
                maxVotes = votes;
                winnerRows.length = 0;
                winnerRows.push(row);
            } else if (votes === maxVotes) {
                winnerRows.push(row);
            }
        }
        /*
         * Only highlight if there is at least one vote.
         */
        if (maxVotes > 0) {
            for (const row of winnerRows) {
                row.classList.add('winner');
            }
        }
    }
    /*
     * Process every election table.
     */
    function highlightAllWinners() {
        const tables = document.querySelectorAll(
            '#sandboxedTable .resultsTable, table.resultsTable'
        );
        if (!tables.length) {
            return;
        }
        for (const table of tables) {
            const tbody =
                table.tBodies && table.tBodies[0]
                    ? table.tBodies[0]
                    : table.querySelector('tbody');
            if (!tbody) {
                continue;
            }
            /*
             * Remove any existing winner highlights first.
             */
            tbody
                .querySelectorAll('.winner')
                .forEach(function (element) {
                    element.classList.remove('winner');
                });
            const rows = Array.from(
                tbody.querySelectorAll('tr')
            );
            let currentRaceRows = [];
            let currentRaceName = '';
            for (let i = 0; i < rows.length; i++) {
                const row = rows[i];
                const isTitleRow =
                    row.querySelector('.raceTitle') ||
                    row.matches(
                        '.raceTitle, [class*=raceTitle]'
                    );
                const isSummaryRow =
                    row.querySelector('.raceSummary') ||
                    row.matches(
                        '.raceSummary, [class*=raceSummary]'
                    );
                /*
                 * New race begins.
                 */
                if (isTitleRow) {
                    /*
                     * Finish the previous race first.
                     */
                    if (currentRaceRows.length) {
                        const numberOfSeats =
                            MULTI_SEAT_RACES[currentRaceName] || 1;
                        if (numberOfSeats > 1) {
                            highlightTopNWinners(
                                currentRaceRows,
                                numberOfSeats
                            );
                        } else {
                            highlightSingleWinner(
                                currentRaceRows
                            );
                        }
                        currentRaceRows = [];
                    }
                    /*
                     * Store the new race name.
                     */
                    currentRaceName =
                        getRaceNameFromTitleRow(row);
                    continue;
                }
                /*
                 * Don't treat summary rows as candidates.
                 */
                if (isSummaryRow) {
                    continue;
                }
                /*
                 * Candidate/option rows have exactly two cells:
                 * candidate name + vote total.
                 */
                const cells = row.querySelectorAll('td');
                if (cells.length === 2) {
                    currentRaceRows.push(row);
                }
            }
            /*
             * Process the final race in the table.
             */
            if (currentRaceRows.length) {
                const numberOfSeats =
                    MULTI_SEAT_RACES[currentRaceName] || 1;
                if (numberOfSeats > 1) {
                    highlightTopNWinners(
                        currentRaceRows,
                        numberOfSeats
                    );
                } else {
                    highlightSingleWinner(
                        currentRaceRows
                    );
                }
            }
        }
    }
    /*
     * Watch for changes to vote totals.
     *
     * This allows the green highlight to update automatically
     * if the election results change without a full page reload.
     */
    function observeVoteChanges() {
        const root =
            document.querySelector('#sandboxedTable') ||
            document.body;
        const observer = new MutationObserver(function () {
            highlightAllWinners();
        });
        observer.observe(root, {
            childList: true,
            subtree: true,
            characterData: true
        });
    }
    /*
     * Initialize.
     */
    function initializeHighlighting() {
        highlightAllWinners();
        observeVoteChanges();
    }
    /*
     * Wait until the page has loaded.
     */
    if (document.readyState === 'loading') {
        document.addEventListener(
            'DOMContentLoaded',
            initializeHighlighting
        );
    } else {
        initializeHighlighting();
    }
})();
